      "A": "錯誤。漏列Ⅲ評估獲利能力。",
      "B": "錯誤。漏列Ⅱ每股盈餘定義。",
      "C": "錯誤。漏列Ⅰ趨勢比較。",
      "D": "正確。Ⅰ、Ⅱ、Ⅲ均為每股盈餘的正確描述。"
