  "109Q3-law-10": {
    "summary": "考點為特別股特性；特別股與普通股每股金額相同，無表決權特別股股東仍可出席股東會，丙丁正確。",
    "options": {
      "A": "錯誤：甲不正確且乙不正確。",
      "B": "正確：丙、丁為正確說明。",
      "C": "錯誤：乙不正確。",
      "D": "錯誤：甲、乙皆不正確。"
    }
  },
  "109Q3-law-11": {
    "summary": "考點為投信事業利害關係公司範圍；董事長配偶持有百分之五股份之公司非屬利害關係公司。",
    "options": {
      "A": "錯誤：法人董事之公司屬利害關係。",
      "B": "錯誤：董事、監察人或持股5%以上股東屬利害關係。",
      "C": "正確：董事長配偶持有5%股份之公司非屬利害關係公司。",
      "D": "錯誤：持有60%股份之公司屬利害關係。"
    }
  },
  "109Q3-law-12": {
    "summary": "考點為同業公會會員業務經營原則；「不公開原則」非共同信守原則，故B為非。",
    "options": {
      "A": "錯誤：公平競爭為應信守原則。",
      "B": "正確：不公開原則非共同信守之業務經營原則。",
      "C": "錯誤：善良管理為應信守原則。",
      "D": "錯誤：忠實誠信為應信守原則。"
    }
  },
  "109Q3-law-13": {
    "summary": "考點為全權委託投資契約審閱期間；簽約前應有7日以上供客戶審閱全部條款。",
    "options": {
      "A": "錯誤：3日不足。",
      "B": "錯誤：5日不足。",
      "C": "正確：應有7日以上審閱期間。",
      "D": "錯誤：10日非法定最低。"
    }
  },
  "109Q3-law-14": {
    "summary": "考點為全權委託投資分析與決定檢討頻率；應每月提出檢討。",
    "options": {
      "A": "錯誤：非每週。與正解不同。",
      "B": "正確：應每月提出檢討。",
      "C": "錯誤：非每季。與正解不同。",
      "D": "錯誤：非每6個月。"
    }
  },
  "109Q3-law-15": {
    "summary": "考點為投信與電子支付機構合作原則；電子支付機構廣告不需主管機關核閱，故D為非。",
    "options": {
      "A": "錯誤：不得誤導投資人為應遵守原則。",
      "B": "錯誤：不得提供短於買回款給付期間服務為應遵守原則。",
      "C": "錯誤：電子支付機構不得涉及銷售及促銷為應遵守原則。",
      "D": "正確：電子支付機構廣告或公開說明會不需事先經主管機關核閱，為本題非遵守事項。"
    }
  },
  "109Q3-law-16": {
    "summary": "考點為投信事業至少設置部門；市場監視非必要部門，故A為非。",
    "options": {
      "A": "正確：市場監視非至少設置之部門。",
      "B": "錯誤：投資研究為必要部門。",
      "C": "錯誤：財務會計為必要部門。",
      "D": "錯誤：內部稽核為必要部門。"
    }
  },
  "109Q3-law-17": {
    "summary": "考點為投信事業董事長資格；需分析人員資格加專業投資機構經驗二年以上。",
    "options": {
      "A": "錯誤：經驗一年不足。",
      "B": "正確：分析人員資格加專業投資機構經驗二年以上。",
      "C": "錯誤：專科畢業加一年經驗不符。",
      "D": "錯誤：此為其他職位資格。"
    }
  },
  "109Q3-law-18": {
    "summary": "考點為投信經理守則性質；多數公司以列舉法令提醒，但未將職業道德標準化。",
    "options": {
      "A": "錯誤：違反守則可能解職。",
      "B": "錯誤：違規可能成為主管機關參考。",
      "C": "錯誤：守則非強制規定。",
      "D": "正確：多數公司僅列舉法令，未標準化職業道德。"
    }
  },
  "109Q3-law-19": {
    "summary": "考點為境外基金總代理人公告期限；暫停及恢復交易應於事實發生日起3日內公告。",
    "options": {
      "A": "錯誤：1日非法定期限。",
      "B": "錯誤：2日非法定期限。",
      "C": "正確：應於3日內公告。",
      "D": "錯誤：5日非法定期限。"
    }
  },
  "109Q3-law-20": {
    "summary": "考點為證券投資顧問經手人員個人交易規範；經手人員不得取得與業務相關之初次上市櫃及興櫃股票。",
    "options": {
      "A": "錯誤：到職10日內申報帳戶為正確規範。",
      "B": "正確：經手人員不得取得與業務相關之初次上市櫃及興櫃股票，即使經許可亦不可。",
      "C": "錯誤：事先書面核准為正確規範。",
      "D": "錯誤：客戶利益優先為正確規範。"
    }
  },
  "109Q3-law-21": {
    "summary": "考點為投信私募受益憑證規範；國外私募投資國內或國內私募投資國外應申報並併中央銀行同意函。",
    "options": {
      "A": "錯誤：對金融業私募人數限制非此。",
      "B": "錯誤：應募人總數限制非35人。",
      "C": "錯誤：申報期限非15日。",
      "D": "正確：應向主管機關申報並併中央銀行同意函影本。"
    }
  },
  "109Q3-law-22": {
    "summary": "考點為財務報告簽章責任；監察人無須簽名或蓋章並出具無虛偽隱匿聲明。",
    "options": {
      "A": "錯誤：董事長須簽章。",
      "B": "錯誤：經理人須簽章。",
      "C": "錯誤：會計主管須簽章。",
      "D": "正確：監察人無須簽章並出具聲明。"
    }
  },
  "109Q3-law-23": {
    "summary": "考點為獨立董事辭任補選；2名獨立董事辭任時應於最近一次股東會補選。",
    "options": {
      "A": "正確：於最近一次股東會補選。",
      "B": "錯誤：非30日內召開臨時會。",
      "C": "錯誤：非60日內召開臨時會。",
      "D": "錯誤：非90日內召開臨時會。"
    }
  },
  "109Q3-law-24": {
    "summary": "考點為控制從屬公司認定；相同股東持有半數以上有表決權股份可推定控制從屬關係，C敘述錯誤。",
    "options": {
      "A": "錯誤：持有超過半數有表決權股份為控制公司。",
      "B": "錯誤：執行業務股東或董事半數以上相同可推定。",
      "C": "正確：相同股東持有半數以上有表決權股份可推定控制從屬，C說無法推定為錯誤。",
      "D": "錯誤：直接或間接控制人事財務業務亦為控制公司。"
    }
  },
  "109Q3-law-25": {
    "summary": "考點為內部控制聲明書申報期限；應於每會計年度終了後3個月內申報。",
    "options": {
      "A": "錯誤：2個月非法定期限。",
      "B": "正確：應於3個月內申報。",
      "C": "錯誤：4個月非法定期限。",
      "D": "錯誤：6個月非法定期限。"
    }
  },
  "109Q3-law-26": {
    "summary": "考點為關係企業書表編製；從屬公司為公開發行公司者應造具與控制公司間關係報告書。",
    "options": {
      "A": "正確：從屬公司為公開發行公司者應造具關係報告書。",
      "B": "錯誤：非合併營業報告書。",
      "C": "錯誤：非合併財務報表。",
      "D": "錯誤：非控制公司造具。"
    }
  },
  "109Q3-law-27": {
    "summary": "考點為員工認股權憑證發行；認股價格不得低於發行日收盤價，C說不得高於收盤價為錯誤。",
    "options": {
      "A": "錯誤：二年後得請求履約為正確。",
      "B": "錯誤：不得轉讓但繼承例外為正確。",
      "C": "正確：認股價格不得低於發行日收盤價，說不得高於為錯誤。",
      "D": "錯誤：存續期間不得超過十年為正確。"
    }
  },
  "109Q3-law-28": {
    "summary": "考點為審計委員會同意事項；總經理任免無須經審計委員會同意。",
    "options": {
      "A": "錯誤：重大資金貸與須同意。",
      "B": "錯誤：私募可轉換公司債須同意。",
      "C": "錯誤：財務會計或內部稽核主管任免須同意。",
      "D": "正確：總經理任免無須審計委員會同意。"
    }
  },
