  "113Q3-law-10": {
    "summary": "考點為公司制證交所使用市場契約；正解D為非正確敘述，相關標準非由公會決定。",
    "options": {
      "A": "正確，公司制證交所應與經紀商或自營商訂立使用市場契約。",
      "B": "正確，契約應約定繳存交割結算基金。",
      "C": "正確，契約應約定繳付證券交易經手費。",
      "D": "此為題目要找的非正確敘述，交割結算基金與經手費標準非由公會決定。"
    }
  },
