      "B": "將原本30%股權按$500重新評價，產生$200評價利益認列當期損益：正確。",
      "C": "將新增投資部分視同合併商譽計入資本公積：處理錯誤。",
      "D": "公允價值增值$200認列其他綜合損益：重分類處理錯誤。"
